@startuml

abstract class Person {
  + FirstName : string
  + LastName : string
}

class Teacher extends Person {
  + Email : string
}

class Student extends Person {}

class TeachingAssignment {
  + Hours : int
}

class School {
  + Name : string
}

class ClassGroup {
  + Name : string
}

abstract class Room {
  + Name : string
}

class ClassRoom extends Room {
  + Capacity : int
}

class OtherRoom extends Room {
  + Size : double
}

School "1" -- "0..3" Teacher : employs
Teacher "1 Principal" -- "0..1" School : principal
Teacher "1" -- "*" TeachingAssignment
TeachingAssignment "*" -- "1" School
Student "*" -- "1" ClassGroup
ClassGroup "1" -- "1" ClassRoom
ClassGroup "1" -- "10..31" Student
School "1" *-- "*" Room
School "1" *-- "*" ClassGroup

@enduml

